<script setup lang="ts">import{ref}from'vue';import{LocalCaseRepository}from'../adapters/local-case.repository';import{BrowserPrintAdapter}from'../adapters/browser-print.adapter';import{useDecisionStudio}from'./useDecisionStudio';import DecisionForm from'./components/DecisionForm.vue';import ValuesPanel from'./components/ValuesPanel.vue';import ResultPanel from'./components/ResultPanel.vue';import CaseLibrary from'./components/CaseLibrary.vue';const studio=useDecisionStudio(new LocalCaseRepository(localStorage),new BrowserPrintAdapter());const tab=ref<'input'|'result'>('input');function analyze(){studio.analyze();if(!studio.errors.value.length)tab.value='result'}function load(item:Parameters<typeof studio.load>[0]){studio.load(item);tab.value=studio.analysis.value?'result':'input'}</script>
<template><div class="decision-app"><header><div class="brand"><b>R</b><div><span>REFLECTION LAB / 006</span><h1>决策后悔模拟器</h1></div></div><nav><button :class="{active:tab==='input'}" @click="tab='input'">01 决策录入</button><button :class="{active:tab==='result'}" :disabled="!studio.analysis.value" @click="tab='result'">02 后悔预演</button></nav><div class="actions"><button @click="studio.save">保存案例</button><button @click="studio.print">打印报告</button><button class="primary" @click="analyze">重新推演 ↗</button></div></header><main><section class="hero"><span>LOOK BACK BEFORE YOU LEAP</span><h2>先去未来看一眼，<br><em>再决定今天怎么选。</em></h2><p>这里没有标准答案。只有价值排序、时间跨度，以及你愿意承担的遗憾。</p></section><div class="layout"><CaseLibrary :cases="studio.cases.value" @load="load" @remove="studio.remove"/><div class="workarea"><template v-if="tab==='input'"><div v-if="studio.errors.value.length" class="errors"><p v-for="error in studio.errors.value" :key="error">{{error}}</p></div><DecisionForm :draft="studio.draft" @touch="studio.touch" @add="studio.addOption" @remove="studio.removeOption" @update="studio.updateOption"/><ValuesPanel :weights="studio.draft.weights" @update="studio.setWeights"/><button class="analyze-button" @click="analyze">生成后悔预演 <span>看看 1 / 5 / 10 年后的自己</span> →</button></template><ResultPanel v-else-if="studio.analysis.value" :analysis="studio.analysis.value" :stale="studio.stale.value"/></div></div></main></div></template>
